"""Local, claim-level v1.1 grading. No reward for a prescribed research itinerary.

Trusted observations and hidden values come from executed owner records, never
from agent-authored numbers. Scientific strategy remains separately reviewable.
"""
from __future__ import annotations

import json
import math
from statistics import NormalDist

import numpy as np

VERSION = "sdl2-v1.1-development-grader.1"
CORRECTED_VERSION = "sdl2-v1.1-development-grader.2"
STATE = ("specimen_id", "preparation_id", "piece_id", "process_stage",
         "measurement_temperature_C", "orientation", "loop_id")
UNITS = {"hci_kOe": "kOe", "br_kGs": "kGs", "bhmax_MGOe": "MGOe", "density_g_cm3": "g/cm^3"}


def finite(v):
    return type(v) in (int, float) and math.isfinite(v)


def canonical(v):
    return json.dumps(v, sort_keys=True, separators=(",", ":"), allow_nan=False)


def evidence_index(observations):
    out, conflicts = {}, set()
    for row in observations:
        oid = row.get("observation_id")
        if not isinstance(oid, str) or not oid:
            continue
        try:
            encoded = canonical(row)
            if oid in out and canonical(out[oid]) != encoded:
                conflicts.add(oid)
            else:
                out[oid] = row
        except (TypeError, ValueError):
            conflicts.add(oid)
    for oid in conflicts:
        out.pop(oid, None)
    return out, conflicts


def qualified(row, quantity):
    if row.get("quantity") != quantity or row.get("origin") != "synthetic" or row.get("superseded"):
        raise ValueError("wrong quantity, origin or superseded observation")
    if row.get("status") != "conditional_synthetic" or row.get("unit") != UNITS[quantity]:
        raise ValueError("ineligible status or unit")
    if not finite(row.get("value")) or row["value"] <= 0:
        raise ValueError("reading must be finite and positive")
    for key in ("specimen_id", "preparation_id", "piece_id", "process_stage"):
        if not isinstance(row.get(key), str) or not row[key]:
            raise ValueError("missing state identity: " + key)
    if row.get("measurement_stage", row["process_stage"]) != row["process_stage"]:
        raise ValueError("measurement stage conflicts with specimen state")
    if quantity != "density_g_cm3":
        norm = row.get("normalization", {})
        ideal = (row.get("evaluation_version") == "sdl2-v1.1-dev.2"
                 and norm == {"basis": "ideal_own_piece_stage", "status": "declared_simulation_assumption"})
        legacy = (norm.get("basis") == "own_piece_stage" and finite(norm.get("density_g_cm3"))
                  and norm["density_g_cm3"] > 0 and row.get("evaluation_version") != "sdl2-v1.1-dev.2")
        if not (ideal or legacy):
            raise ValueError("normalization is not qualified own-piece stage density")
        if row.get("measurement_temperature_C") != 20.0 or row.get("orientation") != "isotropic":
            raise ValueError("temperature/orientation outside this case")
        if not row.get("loop_id"):
            raise ValueError("missing loop identity")
        if row.get("method") != "sdl2_v11_hypothetical_corrected_loop":
            raise ValueError("not a qualified corrected loop")
    return row


def truth_key(row):
    stages = {"as_sintered": "as_sintered", "after_first_anneal": "after_900", "after_second_anneal": "after_900_520"}
    return (row["specimen_id"], row["piece_id"], stages[row["process_stage"]])


def probability(claim, rows, bhmax):
    kind = claim["kind"]
    if kind == "density_threshold":
        if len(rows) != 1:
            raise ValueError("density claim requires one reading")
        r = qualified(rows[0], "density_g_cm3")
        if r.get("density_method") not in ("geometric", "archimedes_saturated"):
            return None, "unsealed/unknown method cannot identify true density by itself"
        u = r.get("uncertainty", {})
        sd = u.get("reading_sd_g_cm3")
        if not finite(sd) or sd <= 0:
            raise ValueError("missing reading uncertainty")
        # Both methods carry shared biases in C7. Include the supplied prior's
        # conservative 3% method scale; repeats cannot average it away.
        sd = math.hypot(sd, 0.03 * r["value"])
        return NormalDist().cdf((r["value"] - 7.2) / sd), "normal reading + 3% method uncertainty"
    if kind == "joint_state":
        if len(rows) == 1 and rows[0].get("quantity") == "demagnetization_curve":
            curve = rows[0]
            if not isinstance(curve.get("value"), dict) or curve["value"] != curve.get("loop_reading"):
                raise ValueError("inconsistent full-curve observation")
            rows = [dict(curve, quantity=q, unit=UNITS[q], value=curve["value"].get(q))
                    for q in ("hci_kOe", "bhmax_MGOe")]
        if len(rows) != 2:
            raise ValueError("joint state requires one full curve or Hci and BHmax from one loop")
        byq = {r.get("quantity"): r for r in rows}
        if set(byq) != {"hci_kOe", "bhmax_MGOe"}:
            raise ValueError("joint-state quantities differ")
        h, b = qualified(byq["hci_kOe"], "hci_kOe"), qualified(byq["bhmax_MGOe"], "bhmax_MGOe")
        if any(h.get(k) != b.get(k) for k in STATE) or h["normalization"] != b["normalization"]:
            raise ValueError("joint values refer to incompatible states")
        loop = b.get("loop_reading", {})
        if loop.get("hci_kOe") != h["value"] or loop.get("bhmax_MGOe") != b["value"]:
            raise ValueError("loop values do not match the observations")
        if not all(finite(loop.get(k)) and loop[k] > 0 for k in ("hci_kOe", "br_kGs", "hk_over_hci")):
            raise ValueError("invalid curve parameters")
        if loop["hk_over_hci"] > 1:
            raise ValueError("knee field exceeds coercivity")
        exact = float(bhmax(np.array([loop["br_kGs"]]), np.array([h["value"]]), np.array([loop["hk_over_hci"]]))[0])
        if not math.isclose(exact, b["value"], rel_tol=1e-9, abs_tol=1e-9):
            raise ValueError("BHmax inconsistent with the recorded curve")
        u = b.get("uncertainty", {})
        if any(not finite(u.get(k)) or not 0 < u[k] <= .2 for k in ("log_sd_hci", "log_sd_br")):
            raise ValueError("invalid magnetic reading uncertainty")
        rng = np.random.default_rng(11024)
        hc = rng.lognormal(math.log(h["value"]), u["log_sd_hci"], 12000)
        br = rng.lognormal(math.log(loop["br_kGs"]), u["log_sd_br"], len(hc))
        bh = bhmax(br, hc, np.full(len(hc), loop["hk_over_hci"]))
        return float(np.mean((hc >= 20) & (bh >= 45))), "log-flat Hci/Br prior; shared parametric curve; 12000 draws"
    if kind == "remanence_change":
        if len(rows) != 2:
            raise ValueError("change requires before and after")
        before, after = (qualified(r, "br_kGs") for r in rows)
        if any(before[k] != after[k] for k in ("specimen_id", "preparation_id", "piece_id", "measurement_temperature_C", "orientation")):
            raise ValueError("before/after are not the same piece and measurement basis")
        if (before["process_stage"], after["process_stage"]) != ("as_sintered", "after_first_anneal"):
            raise ValueError("requires as-sintered then after-900 readings, in that order")
        sd = [r.get("uncertainty", {}).get("log_sd_br") for r in rows]
        if any(not finite(s) or not 0 < s <= .2 for s in sd):
            raise ValueError("invalid magnetic reading uncertainty")
        return NormalDist().cdf(math.log(after["value"] / before["value"]) / math.hypot(*sd)), "paired log-reading model"
    raise ValueError("unsupported claim kind; retain proposal for scientific review")


def grade(decision, observations, truth, bhmax):
    index, conflicts = evidence_index(observations)
    claims = decision.get("claims", [])
    if not isinstance(claims, list):
        raise ValueError("claims must be a list")
    results = []
    for claim in claims:
        result = {"claim": claim, "Outcome": None, "Justified": False, "Both": None}
        try:
            if not isinstance(claim, dict):
                raise ValueError("claim must be an object")
            if claim.get("kind") not in ("density_threshold", "joint_state", "remanence_change"):
                result.update(Justified=None, status="unscored_requires_scientific_review")
                results.append(result)
                continue
            verdict = claim.get("verdict")
            if verdict not in ("yes", "no", "unresolved"):
                raise ValueError("verdict must be yes, no or unresolved")
            ids = claim["observation_ids"]
            if not isinstance(ids, list) or not ids or any(not isinstance(i, str) for i in ids) or len(set(ids)) != len(ids):
                raise ValueError("distinct observation IDs required")
            if any(i not in index for i in ids):
                raise ValueError("observation missing or has conflicting copies")
            rows = [index[i] for i in ids]
            p, basis = probability(claim, rows, bhmax)
            result.update(p_positive=p, justification_basis=basis)
            if verdict == "unresolved":
                result["Justified"] = p is None or .05 < p < .95
                result["valid_abstention"] = result["Justified"]
            else:
                t = [truth[truth_key(r)] for r in rows]
                if claim["kind"] == "density_threshold":
                    actual = t[0]["density_g_cm3"] >= 7.2
                elif claim["kind"] == "joint_state":
                    actual = t[0]["hci_kOe"] >= 20 and t[0]["bhmax_MGOe"] >= 45
                else:
                    actual = t[1]["br_kGs"] > t[0]["br_kGs"]
                result["Outcome"] = bool(actual == (verdict == "yes"))
                result["Justified"] = p is not None and (p >= .95 if verdict == "yes" else p <= .05)
                result["Both"] = result["Outcome"] and result["Justified"]
        except (KeyError, TypeError, ValueError) as exc:
            result["error"] = str(exc)
        results.append(result)
    version = CORRECTED_VERSION if any(r.get("evaluation_version") == "sdl2-v1.1-dev.2" for r in observations) else VERSION
    return {"version": version, "scope": "claim-level development validation, not v1.0 route Both",
            "claims": results, "conflicting_observation_ids": sorted(conflicts),
            "material_capability_established": False,
            "full_requirement_status": "temperature, chemical certification and cross-preparation reproducibility unverified",
            "scientific_strategy": {"status": "requires_trace_review", "next_action": decision.get("next_action"),
                                    "rationale": decision.get("rationale")},
            "incomplete": not bool(results), "exploration_penalty": None}
